    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long first = r.nextLong(), prev = first, fall = 0, rise = 0;  // total adjacent decreases / increases
        for (int i = 1; i < n; i++) {
