	first := readInt()
	prev, fall, rise := first, 0, 0 // total adjacent decreases / increases
	for i := 1; i < n; i++ {
		v := readInt()
		if v < prev {
			fall += prev - v
		} else {
			rise += v - prev
		}
		prev = v
	}
	c := first - fall
	if c < 0 {
		c = -c
	}
	fmt.Println(fall + rise + c)
}

